DROP TABLE IF EXISTS payments, shuffled CASCADE;
CREATE TABLE payments (id bigint, merchant_id int, currency text, status text,
                       amount_cents bigint, created_at timestamp);
INSERT INTO payments
  SELECT g, 1 + (g * 7919) % 10000,
         (ARRAY['EUR','EUR','EUR','GBP','USD','SEK'])[1 + (g * 31) % 6],
         CASE WHEN g % 50 = 0 THEN 'refunded' WHEN g % 20 = 0 THEN 'failed' ELSE 'settled' END,
         (g * 104729) % 100000,
         TIMESTAMP '2026-10-01' + g * interval '2 seconds'
  FROM generate_series(1, 1000000::bigint) g;
VACUUM ANALYZE payments;

SELECT pg_size_pretty(pg_relation_size('payments')) AS heap, relpages FROM pg_class WHERE relname = 'payments';
SELECT avg(pg_column_size(p.*))::int AS row_bytes, avg(pg_column_size(p.amount_cents))::int AS amount_bytes
FROM payments p;
SET max_parallel_workers_per_gather = 0;
EXPLAIN (ANALYZE, BUFFERS, COSTS OFF, TIMING OFF, SUMMARY OFF) SELECT sum(amount_cents) FROM payments;

SET max_parallel_workers_per_gather = 0;
CREATE INDEX payments_created_brin ON payments USING brin (created_at);
SELECT pg_size_pretty(pg_relation_size('payments_created_brin')) AS brin_size;
EXPLAIN (ANALYZE, BUFFERS, COSTS OFF, TIMING OFF, SUMMARY OFF)
  SELECT count(*), sum(amount_cents) FROM payments
  WHERE created_at >= '2026-10-15' AND created_at < '2026-10-16';
CREATE INDEX payments_created_btree ON payments (created_at);
SELECT pg_size_pretty(pg_relation_size('payments_created_btree')) AS btree_size;
DROP INDEX payments_created_btree;

CREATE TABLE shuffled AS SELECT * FROM payments ORDER BY md5(id::text);
CREATE INDEX shuffled_created_brin ON shuffled USING brin (created_at);
VACUUM ANALYZE shuffled;
SET enable_seqscan = off;
EXPLAIN (ANALYZE, BUFFERS, COSTS OFF, TIMING OFF, SUMMARY OFF)
  SELECT count(*), sum(amount_cents) FROM shuffled
  WHERE created_at >= '2026-10-15' AND created_at < '2026-10-16';
RESET ALL;

